const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/**
 * Parses election text into a candidate list and a ballot list, or throws an
 * `ElectionError` describing the first problem found. Input lines are
 * numbered from 1, including blank and comment lines, since error messages
 * cite the original line number.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive !== 'candidates' && directive !== 'ballot') {
      throw new ElectionError(lineNumber, `unknown directive ${directive}`)
    }

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ElectionError(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ElectionError(lineNumber, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ElectionError(lineNumber, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new ElectionError(lineNumber, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
      continue
    }

    // directive === 'ballot'
    if (candidates === null) {
      throw new ElectionError(lineNumber, 'candidates must be declared once, before any ballot')
    }
    if (tokens.length < 3) {
      throw new ElectionError(lineNumber, 'expected ballot <count> <candidate>...')
    }
    const countText = tokens[1]
    if (!COUNT_PATTERN.test(countText)) {
      throw new ElectionError(lineNumber, 'count must be a positive integer')
    }
    const names = tokens.slice(2)
    const seen = new Set()
    for (const name of names) {
      if (!candidateSet.has(name)) {
        throw new ElectionError(lineNumber, `unknown candidate ${name}`)
      }
      if (seen.has(name)) {
        throw new ElectionError(lineNumber, `candidate ${name} is repeated`)
      }
      seen.add(name)
    }
    ballots.push({ count: Number(countText), candidates: names })
  }

  if (candidates === null) {
    throw new ElectionError(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

