{"file_path":"./src/count.js","content":"/**
 * Runs an instant-runoff count. Returns `{ rounds, winner }` where `rounds`
 * is one entry per round counted, `{ counts, exhausted, eliminated }` with
 * `counts` a `Map` from candidate name to that round's vote count for every
 * candidate still continuing at the start of the round, and `eliminated`
 * the name removed after the round or `null` for the last round. `winner`
 * is the winning candidate's name or `null` when nobody reached a majority.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.candidates.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    let activeTotal = 0
    for (const votes of counts.values()) activeTotal += votes

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const majorityWinner = [...counts.entries()].find(([, votes]) => votes * 2 > activeTotal)
    if (majorityWinner !== undefined) {
      winner = majorityWinner[0]
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const toEliminate = chooseElimination(counts, rounds)
    rounds.push({ counts, exhausted, eliminated: toEliminate })
    continuing = new Set([...continuing].filter((name) => name !== toEliminate))
  }

  return { rounds, winner }
}

/**
 * Picks which of this round's lowest-scoring candidates to eliminate,
 * breaking ties by their history across earlier rounds (this one included)
 * from the first round onwards, and finally by reverse name order.
 */
function chooseElimination(counts, priorRounds) {
  const minVotes = Math.min(...counts.values())
  let tied = [...counts.entries()].filter(([, votes]) => votes === minVotes).map(([name]) => name)

  const history = [...priorRounds.map((round) => round.counts), counts]

  for (const roundCounts of history) {
    if (tied.length === 1) break
    const values = tied.map((name) => roundCounts.get(name))
    const allEqual = values.every((v) => v === values[0])
    if (allEqual) continue
    const min = Math.min(...values)
    tied = tied.filter((name) => roundCounts.get(name) === min)
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

