{"file_path":"./src/format.js","content":"/**
 * Renders the candidates of one round, descending by vote count and then
 * ascending by name, as `name=votes` pairs.
 */
function formatCounts(counts) {
  const entries = [...counts.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesB - votesA
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  return entries.map(([name, votes]) => `${name}=${votes}`).join(' ')
}

function formatOutcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

/** Renders the full `rounds` mode transcript. */
export function formatRounds(rounds, winner) {
  const lines = []
  rounds.forEach((round, index) => {
    lines.push(`round ${index + 1}: ${formatCounts(round.counts)} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(formatOutcome(winner))
  return lines.map((line) => `${line}\n`).join('')
}

/** Renders the `tally` mode summary. */
export function formatTally(rounds, winner) {
  return `rounds ${rounds.length}\n${formatOutcome(winner)}\n`
}
"}

