import { runElection } from './count.js'
import { formatRounds, formatTally } from './format.js'
import { ElectionError } from './errors.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const [mode] = process.argv.slice(2)
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (error) {
    if (error instanceof ElectionError) {
      fail(error.line === null ? error.message : `line ${error.line}: ${error.message}`)
      return
    }
    throw error
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(rounds, winner) : formatTally(rounds, winner)
  process.stdout.write(output)
  process.exit(0)
}

